function useCountUp(target: number, duration = 1500) {
  const [value, setValue] = useState(0)
  const ref = useRef<HTMLDivElement>(null)
  const started = useRef(false)

  useEffect(() => {
    const element = ref.current
    if (!element) return

    const observer = new IntersectionObserver(([entry]) => {
      if (!entry.isIntersecting || started.current) return
      started.current = true
      const start = performance.now()

      const tick = (now: number) => {
        const progress = Math.min((now - start) / duration, 1)
        const eased = 1 - Math.pow(1 - progress, 3)
        setValue(Math.round(eased * target))
        if (progress < 1) requestAnimationFrame(tick)
      }

      requestAnimationFrame(tick)
    }, { threshold: 0.3 })

    observer.observe(element)
    return () => observer.disconnect()
  }, [duration, target])

  return { value, ref }
}

function AnimatedStat({ value, prefix = '', suffix = '', label }: {
  value: number
  prefix?: string
  suffix?: string
  label: string
}) {
  const count = useCountUp(value)

  return (
    <div ref={count.ref} className="text-center">
      <div className="font-bold leading-none" style={{ color: '#3b84ff', fontSize: 'clamp(2rem,4vw,3rem)' }}>
        {prefix}{count.value.toLocaleString()}{suffix}
      </div>
      <div className="mt-2 text-xs font-semibold uppercase tracking-widest" style={{ color: 'rgba(20,15,12,.46)' }}>
        {label}
      </div>
    </div>
  )
}

function FadeIn({ children, delay = 0 }: { children: ReactNode; delay?: number }) {
  const ref = useRef<HTMLDivElement>(null)
  const [visible, setVisible] = useState(false)

  useEffect(() => {
    const element = ref.current
    if (!element) return
    const observer = new IntersectionObserver(([entry]) => {
      if (entry.isIntersecting) setVisible(true)
    }, { threshold: 0.08 })
    observer.observe(element)
    return () => observer.disconnect()
  }, [])

  return (
    <div ref={ref} style={{
      opacity: visible ? 1 : 0,
      transform: visible ? 'translateY(0)' : 'translateY(18px)',
      transition: 'opacity .55s ease, transform .55s ease',
      transitionDelay: delay + 'ms',
    }}>
      {children}
    </div>
  )
}

function TableOfContents() {
  const [active, setActive] = useState('exec-summary')

  useEffect(() => {
    const observers: IntersectionObserver[] = []

    TOC_ITEMS.forEach((item) => {
      const element = document.getElementById(item.id)
      if (!element) return
      const observer = new IntersectionObserver(([entry]) => {
        if (entry.isIntersecting) setActive(item.id)
      }, { rootMargin: '-18% 0px -70% 0px', threshold: 0 })
      observer.observe(element)
      observers.push(observer)
    })

    return () => observers.forEach((observer) => observer.disconnect())
  }, [])

  return (
    <nav aria-label="Whitepaper contents">
      <p className="mb-4 text-xs font-bold uppercase tracking-widest" style={{ color: 'rgba(20,15,12,.36)' }}>Contents</p>
      <ul className="space-y-1">
        {TOC_ITEMS.map((item) => (
          <li key={item.id}>
            <button
              type="button"
              onClick={() => document.getElementById(item.id)?.scrollIntoView({ behavior: 'smooth', block: 'start' })}
              className="w-full border-l-2 px-2 py-1 text-left text-xs leading-snug transition-colors"
              style={{
                color: active === item.id ? '#3b84ff' : 'rgba(20,15,12,.5)',
                background: active === item.id ? 'rgba(59,132,255,.07)' : 'transparent',
                borderColor: active === item.id ? '#3b84ff' : 'transparent',
                fontWeight: active === item.id ? 650 : 400,
              }}
            >
              {item.label}
            </button>
          </li>
        ))}
      </ul>
    </nav>
  )
}

function formatDate(value?: string) {
  if (!value) return ''
  try {
    return new Date(value).toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' })
  } catch {
    return ''
  }
}

export default function PricingPerformance({ post }: Props) {
  const articleRef = useRef<HTMLElement>(null)
  const title = post?.title || 'The Price You Set Is Not the Price You Get'
  const excerpt = post?.excerpt || 'Managing the Price Realization Gap Across the Wealth Management Book'
  const author = post?.author?.name || 'PureFacts Financial Solutions'
  const publishedAt = formatDate(post?.publishedAt)

  useEffect(() => {
    const article = articleRef.current
    if (!article) return

    const elements = Array.from(article.querySelectorAll('h1,h2,p,table,ul,ol'))
    const observer = new IntersectionObserver((entries) => {
      entries.forEach((entry) => {
        if (entry.isIntersecting) {
          entry.target.classList.add('is-visible')
          observer.unobserve(entry.target)
        }
      })
    }, { threshold: 0.04 })

    elements.forEach((element) => {
      element.classList.add('pp-reveal')
      observer.observe(element)
    })

    return () => observer.disconnect()
  }, [])

  return (
    <main style={{ background: '#fff', color: '#140f0c', fontFamily: 'Carlito, sans-serif' }}>
      <style>{PAGE_STYLES}</style>

      <section className="relative px-6 pb-16 pt-20" style={{ background: '#f4f4f4', borderBottom: '1px solid rgba(20,15,12,.08)' }}>
        <div className="mx-auto max-w-5xl">
          <FadeIn>
            <p className="mb-4 text-xs font-bold uppercase tracking-widest" style={{ color: '#fb5607' }}>Whitepaper</p>
            <h1 className="mb-5 max-w-4xl font-bold leading-tight" style={{ color: '#140f0c', fontSize: 'clamp(2.2rem,5vw,3.75rem)' }}>
              {title}
            </h1>
            <p className="mb-4 max-w-3xl text-xl leading-relaxed" style={{ color: 'rgba(20,15,12,.62)' }}>{excerpt}</p>
            <p className="max-w-2xl text-base font-semibold" style={{ color: 'rgba(20,15,12,.52)' }}>
              Pricing variation is not inherently a problem. Unexplained and unmanaged variation is.
            </p>
          </FadeIn>

          <div className="my-12 h-px w-full" style={{ background: 'linear-gradient(90deg,#FACC22,#FB5607,#4760FF,#0DCCFF)', opacity: .75 }} />

          <div className="mb-10 grid grid-cols-2 gap-8 md:grid-cols-4">
            <AnimatedStat value={66} suffix=" bps" label="Average pricing above $10M" />
            <AnimatedStat value={52} suffix="%" label="Retainer growth since 2023" />
            <AnimatedStat value={43} suffix="%" label="Repriced new clients only" />
            <AnimatedStat value={5} label="Available book decisions" />
          </div>

          <div className="flex items-center justify-center gap-3 border-t pt-5 text-xs" style={{ borderColor: 'rgba(20,15,12,.1)', color: 'rgba(20,15,12,.48)' }}>
            <span className="font-semibold">{author}</span>
            {publishedAt && <><span aria-hidden="true">•</span><span>{publishedAt}</span></>}
          </div>
        </div>
      </section>

      <div className="mx-auto flex max-w-6xl items-start gap-16 px-6 py-16">
        <article
          ref={articleRef}
          className="pp-article min-w-0 flex-1"
          dangerouslySetInnerHTML={{ __html: ARTICLE_HTML }}
        />
        <aside className="sticky top-24 hidden w-64 shrink-0 xl:block">
          <TableOfContents />
        </aside>
      </div>

      <section className="px-6 py-16" style={{ background: '#142f49' }}>
        <FadeIn>
          <div className="mx-auto max-w-4xl text-center">
            <p className="mb-3 text-xs font-bold uppercase tracking-widest" style={{ color: '#0dccff' }}>Put pricing insight into action</p>
            <h2 className="mb-5 text-3xl font-bold text-white">Manage the why behind every price.</h2>
            <p className="mx-auto mb-8 max-w-2xl leading-relaxed" style={{ color: 'rgba(255,255,255,.72)' }}>
              Connect realized pricing, relationship context, advisor workflows and governed exceptions through a single Revenue Book of Record.
            </p>
            <a href="/platform/practice-management" className="inline-flex items-center bg-white px-6 py-3 text-sm font-bold transition-opacity hover:opacity-90" style={{ color: '#142f49' }}>
              Explore Practice Management
            </a>
          </div>
        </FadeIn>
      </section>
    </main>
  )
}

